void Screen1ViewBase::flexButtonCallbackHandler(const touchgfx::AbstractButtonContainer& src)
{
    if (&src == &zoomButton1)
    {
        //Interaction1
        //When zoomButton1 clicked call virtual function
        //Call zoom1X
        zoom1X();
    }
    if (&src == &zoomButton2)
    {
        //Interaction2
        //When zoomButton2 clicked call virtual function
        //Call zoom2X
        zoom2X();
    }
    if (&src == &zoomButton3)
    {
        //Interaction3
        //When zoomButton3 clicked call virtual function
        //Call zoom4X
        zoom4X();
    }
    if (&src == &zoomButton4)
    {
        //Interaction4
        //When zoomButton4 clicked call virtual function
        //Call zoom8X
        zoom8X();
    }
}
